@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const lease=document.querySelector('#lease'),previous=document.querySelector('#previous'),price=document.querySelector('#price'),photo=document.querySelector('#photo'),analyze=document.querySelector('#analyze'),reading=document.querySelector('#meter_reading'),consumption=document.querySelector('#consumption'),amount=document.querySelector('#amount'),box=document.querySelector('#ocr-result'),message=document.querySelector('#ocr-message'),ocrReading=document.querySelector('#ocr_reading'),ocrConfidence=document.querySelector('#ocr_confidence');function syncLease(){const o=lease.selectedOptions[0];previous.value=o?.dataset.previous||'';price.value=o?.dataset.price?`R$ ${Number(o.dataset.price).toFixed(4)}`:'';calculate()}function calculate(){const use=Number(reading.value)-Number(previous.value);if(reading.value&&previous.value!==''&&use>=0){consumption.textContent=`${use.toFixed(3)} kWh`;amount.textContent=`R$ ${(use*Number(lease.selectedOptions[0]?.dataset.price||0)).toFixed(2).replace('.',',')}`}else{consumption.textContent='—';amount.textContent='—'}}lease.addEventListener('change',syncLease);reading.addEventListener('input',calculate);photo.addEventListener('change',()=>analyze.disabled=!photo.files?.[0]);analyze.addEventListener('click',async()=>{analyze.disabled=true;analyze.textContent='Analisando…';const data=new FormData();data.append('photo',photo.files[0]);try{const response=await fetch('{{ route('admin.solar.analyze') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body:data});const result=await response.json();box.hidden=false;if(result.reading!==null&&result.reading!==undefined){reading.value=result.reading;ocrReading.value=result.reading;ocrConfidence.value=result.confidence||0;message.textContent=`${result.reading} kWh · confiança ${Math.round((result.confidence||0)*100)}%. Confira e corrija se necessário.`}else{message.textContent=result.message||'Não foi possível ler o visor. Informe manualmente.'}calculate()}catch(e){box.hidden=false;message.textContent='OCR indisponível. Informe a leitura manualmente.'}finally{analyze.disabled=false;analyze.innerHTML='Ler novamente'}});syncLease()});</script>@endpush
